import React from "react";

export default function PlasmaLavaLampBackground() {
  return (
    <div className="absolute inset-0 w-full h-full overflow-hidden pointer-events-none">
      {/* Use CSS-driven blobs for better cross-browser animation support */}
      <div className="plasma-blob blob-a" aria-hidden />
      <div className="plasma-blob blob-b" aria-hidden />
      <div className="plasma-blob blob-c" aria-hidden />

      <style>{`
        .plasma-blob { position: absolute; border-radius: 50%; filter: blur(48px); mix-blend-mode: screen; opacity: 0.18; }
        .plasma-blob.blob-a { width: 520px; height: 320px; left: 6%; top: 6%; background: radial-gradient(circle at 30% 30%, #ff6f61, transparent 45%); animation: blobMoveA 9s ease-in-out infinite; }
        .plasma-blob.blob-b { width: 640px; height: 420px; right: 6%; bottom: 8%; background: radial-gradient(circle at 70% 70%, #00eaff, transparent 45%); opacity: 0.14; animation: blobMoveB 11s ease-in-out infinite; }
        .plasma-blob.blob-c { width: 420px; height: 300px; right: 24%; top: 18%; background: radial-gradient(circle at 40% 60%, #f44336, transparent 45%); opacity: 0.12; animation: blobMoveC 13s ease-in-out infinite; }

        @keyframes blobMoveA { 0% { transform: translate(0,0) scale(1); } 50% { transform: translate(40px,30px) scale(1.05); } 100% { transform: translate(0,0) scale(1); } }
        @keyframes blobMoveB { 0% { transform: translate(0,0) scale(1); } 50% { transform: translate(-30px,-20px) scale(1.04); } 100% { transform: translate(0,0) scale(1); } }
        @keyframes blobMoveC { 0% { transform: translate(0,0) scale(1); } 50% { transform: translate(-20px,18px) scale(1.03); } 100% { transform: translate(0,0) scale(1); } }
      `}</style>
    </div>
  );
}
